DIGITS = "0123456789"


def encode(text):
    """Run-length encode text that holds no digits. See TASK.md."""
    for ch in text:
        if ch in DIGITS:
            raise ValueError("text to encode must not contain digits")
    out = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        j = i
        while j < n and text[j] == ch:
            j += 1
        run = j - i
        if run == 1:
            out.append(ch)
        else:
            out.append(str(run))
            out.append(ch)
        i = j
    return "".join(out)


def decode(text):
    """Reverse `encode`. See TASK.md."""
    out = []
    i = 0
    n = len(text)
    while i < n:
        if text[i] in DIGITS:
            start = i
            while i < n and text[i] in DIGITS:
                i += 1
            digits = text[start:i]
            if i >= n:
                raise ValueError("count with no character after it: %r" % digits)
            if digits[0] == "0":
                raise ValueError("count with leading zero: %r" % digits)
            count = int(digits)
            if count < 2:
                raise ValueError("count must be 2 or more: %r" % digits)
            out.append(text[i] * count)
            i += 1
        else:
            out.append(text[i])
            i += 1
    return "".join(out)
